/*【青梅煮酒】作者：易碎蝶
①本美化免费发布于尾巴镇，禁止二传二改倒卖，使用二传美化我也不会原谅，如果你是买来的恭喜你为二传做了贡献
②部分代码用到了其他老师分享的，有标注~
③仅限于在正规渠道由本人发布后下载获取，一切其他方式获得皆视为二传，抓到必究
④用我美化的内鬼祝你全家暴毙口牙*/


/* ====== 全局字体====== */
@import url("https://fontsapi.zeoseven.com/309/main/result.css");

body {
    font-family: "KingHwaOldSong";
    font-weight: normal;
}

/*———————— 顶栏 ————————*/
#top-bar {
    position: fixed !important;  
    overflow: visible !important;
    background: none !important;
    border: 0 !important;
    box-shadow: none !important;
    pointer-events: none;
    width: 100vw;  /*宽度*/
    height: 100px;  
    top: 0;
    left: 0;
}

#top-bar::before {
    content: "";
    position: fixed;
    background:  url("https://iili.io/fbQ1HGe.png") no-repeat center / cover;  

    /*⭕️顶栏核心 */
    top: 0px;
    left: 0px;
    right: 0px;
    bottom: 50px;/*⭕️只有这里需要改*/


    z-index: 5;
    pointer-events: auto;

    transform: none !important;
    animation: none !important;
}

/* ⭕️顶栏装饰层 */
#top-bar::after {
      pointer-events: none; /* 点击会穿透到下层元素 */
    content: "";
    position: fixed;
    background: url("") no-repeat center / contain;
    width: 260px;
    height: 200px;
    top: -65px;
    right: 80px;
    z-index: 6;

    transform-origin: top center;
}






/* —————面板背景———— */
.drawer-content {
 background-image: url('https://iili.io/fbQ1F8x.png'); /* 面板背景 */
  background-size: cover; 
  background-position: center; 
  background-repeat: no-repeat; 
  background-attachment: fixed; 
}


/* ===== ⭕️楼层箭头、计数器核心 ===== */
.fa-chevron-right:before,
.fa-chevron-left:before,
.fa-arrow-right:before {
  content: "" !important;
  display: none !important; 
}

.fa-chevron-left,
.fa-chevron-right {
  display: inline-block;
  width: 37px;
  height: 37px; 
  min-width: 0;
  opacity: 1 !important; 
  background: center/contain no-repeat;
opacity: 1 !important;
}

.fa-chevron-left {
  background-image: url('https://iili.io/fbQ1atI.png'); /* 左 */
  margin-bottom: -62px; 

padding: 0px 0px 0;
}
.fa-chevron-right {
  background-image: url('https://iili.io/fbQ1lnt.png'); /* 右 */
  top: 50% !important;
  left: 0% !important;
  transform: translate(-120%, 150%) !important;
  z-index: 9999 !important;
}
/* ===== 楼层计数器样式 ===== */
.swipes-counter {
  font-size: 9px;
  font-weight: 540;
  opacity: 0.9 !important;
  color: #A4A4A4 !important;
}
.swipes-counter {
  position: absolute;
  top: 66px;
  right: 126px;
  z-index: 9999;
  pointer-events: none;
}

/* ==============================================
🦋气泡拼接开始🦋 *==============================================*/

/* 🍃上层装饰层、拼接气泡顶部 */
.mes::before {
  content: "";
  position: absolute;
  top: -50px; /* 【上下】(负值向上) */
  left: -0px; /* 【左右】 */
  width: 358px; /* 【宽度/大小】 */
  height: 590px; /* 【高度/大小】 */
  background-image: url('https://iili.io/fbQ14AQ.png'); 
  background-size: contain; 
  background-repeat: no-repeat; 
  z-index: -2; 
  pointer-events: none; 
}


/* 🍃 中层气泡*/
.mes {
   z-index: -3;
  max-width: 425px;/*【🍃宽度】*/
  width: 100%;/*【👁宽度，一般调整第一个就行，没效果再调整这个】*/
  margin: 55px auto 120px;/*【AI和用户的气泡距离⭕️第一个是调整最早的消息与顶部的距离防止顶部超过屏幕】*/
  border-radius: 0px;
  background: url('https://iili.io/fbQ1kPe.png') repeat-y; 
  background-size: 100% auto; 
  background-attachment: local; 
  transition: transform 0.2s ease; 
  transform-origin: top center;
  position: relative;
  overflow: visible;
  box-shadow: none !important; 
}
/* 🍃下层装饰层、拼接气泡尾部 */
.mes::after {
  content: "";
  position: absolute;
  bottom: -188px; /* 【上下】(负值向下) */
  right: -0px; /* 下层装饰层【左右】 */
  width: 358px; /* 【宽度/大小】 */
  height: 221px; /* 【高度/大小👁会影响最新消息的底部留白，不可调太高，宽度拉不动再调高一点】 */
  background-image: url('https://iili.io/fbQ1Scb.png'); 
background-size: contain; 
  background-repeat: no-repeat;
  z-index: -4; 
  pointer-events: none; 
}

/*——————🍃文本边距——————*/

 .mes_text,
.mes_reasoning {
    font-weight: 300; 
    line-height: 1.9; /* 行高 */
    text-align: justify; 
    text-justify: inter-word; 
    overflow-wrap: anywhere;
    hyphens: auto; 

    /* 优化后的间距系统 */
    --top-padding: 14.5rem;    /* 顶部 */
    --bottom-padding: 1rem; /* 底部 */
    --left-padding: 0.3rem;  /* 左侧 */
    --right-padding: 1rem; /* 右侧 */


    padding: var(--top-padding) var(--right-padding) var(--bottom-padding) var(--left-padding);

    max-width: 100ch;

    margin: 0 auto; 

    /* 高级排版增强 */
    font-kerning: normal; 
    letter-spacing: 0.01em; 
    text-rendering: optimizeLegibility; 
}

.mes_reasoning::first-letter {
    font-weight: 600;
    margin-right: 0.5em;
}
/*@咩野老师*/
.mes_text {
  /* 文字两端对齐justify，左对齐改成left，居中改成center  */
  text-align: justify;
}

/* ==============================================
🦋气泡拼接结束🍃头像美化开始============================================== */


/*⭕️头像框*/
.mesAvatarWrapper {
  position: absolute;
  top: -147px;
  left: 48.9%;
  transform: translateX(-50%);
  z-index: -1;
  width: 70px;  
  height: 70px; 
  overflow: visible; 
}

/* ⭕️头像框位置与大小调整核心 */
.mesAvatarWrapper::after {
  content: "";
  position: absolute;
  top: 98%;/* 【上下】 */
  left: 76%;/* 【左右】 */
  width: 225%;  /* 【框宽度】 */
  height: 235%; /* 【框高度】 */
  display: block;

  /* ⭕️头像框链接放置处 */
  background-image: url('https://iili.io/fbQ1soP.png');/*←🍃*/
  background-size: 100% 100%;
  background-repeat: no-repeat;
  background-position: center;
  transform: translate(-50%, -50%);
  z-index: 1; 

}

.mesAvatarWrapper img {
  position: relative;
  z-index: -1; 
}

/* ⭕️头像位置 */
.mesAvatarWrapper {
  position: absolute;
  top: -27px;           /* 【负值向上】 */
  left: 20%;            /* 【头像左右】 */
  transform: translateX(-50%);
  z-index: -1;
    filter: 
    saturate(1) !important;
}

/* ⭕️头像尺寸*/
.mesAvatarWrapper .avatar {
  /* 🍃头像尺寸 */
  width: 100px;           /* 宽度 */
  height: 110px;          /* 高度 */
  transform: rotate(-0deg); /* 旋转 */
}
.mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ⭕user设置页面/角色选择头像美化⭕*/
/*收藏头像黄圈隐藏、名字颜色修改@Little YE*/
.character_select.is_fav .avatar {
  outline: none !important;
}
.character_select.is_fav .ch_name {
  color: #a9b39b !important;
}
.avatar img {
    border: 2px solid white; /* 头像描边 */
box-shadow:
  0px 2px 2px rgba(101, 103, 63, 0.30);
transform: rotate(-9deg); /* 旋转 */
}

/* ==============================================
🦋头像美化结束🍃文字效果美化开始============================================== */
/*去除提示词阴影@①点这里*/

#completion_prompt_manager .completion_prompt_manager_header_advanced span {
filter: none;
}

/* === 设置选项=== */
small {
  color: #696947 !important;
  opacity: 1;
}
.toggle-description {
    color: #696947;
}
#completion_prompt_manager .completion_prompt_manager_header div {
    color: #696947; /*字符*/
}

.fa-solid::before, .fa-regular::before {
    vertical-align: middle;
    text-align: center;
}

.right_menu_button {
    padding: 0px;
    filter: none;
    color: #696947 !important; /* 更新文字颜色 */
}

/*世界书激活时按钮颜色*/
.world_set, .toggleEnabled {
    color: #7d9366 !important;
}
/*角色收藏时按钮颜色*/
.fav_on {
    color: #7d9366 !important;
}
/* === 预设区文字颜色 === */
/* 选中 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #696947;
}

/* 未选 */
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name, 
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: #a9b39b;
}

/* 星号等标识颜色*/
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt .completion_prompt_manager_prompt_name .fa-solid {
    color: #a9b39b;
}

/* 代码块 */
code, pre {
  background: url('https://iili.io/fbQ1KyQ.png') repeat-y !important;
background-size: 100% auto !important;
  color: #787850 !important; 
  border: 0px solid #ffffff !important; 

box-shadow:
  2px 2px 1px rgba(101, 103, 63, 0.10);
  border-radius: 0px !important; 
padding: 2px 6px;
line-height: 1.5; 
}


code, pre {
  position: relative;
  overflow: visible !important;
}
/* 引用气泡 */
.mes_text q {
    background: none !important; 
    border: 0px solid #f8e4ef !important;
    background: none !important;
border-bottom: 1.2px dotted #9e9e76 !important; /* 点状虚线 */
-webkit-box-decoration-break: clone;

    border-radius: 0px !important;
    padding: 0px 0px 0px 0px !important;
    font-weight: 300;
    line-height: 1;
}


/* 引用区块 */
.mes_text blockquote, 
.mes_reasoning blockquote {
  border-left:2px solid #9e9e76 !important;
  background: url('https://iili.io/fbQEnR4.png') center/cover, #fff !important;
  color: #6f6951 !important; 
  box-shadow:
  2px 2px 1px rgba(101, 103, 63, 0.10);
  border-radius: 0px !important; 

}
.mes_text blockquote,
.mes_reasoning blockquote {
    padding-left: 8px;
    padding-right: 10px;
}
/* 斜体 */
em, i {
  background: rgba(255, 255, 255, 0) !important;
box-shadow:1px 1px 3px rgba(0, 0, 0, 0);
padding: 0px 0px;
}
/* ==============================================
🦋文字效果美化结束🍃零碎美化开始============================================== */

/*—— 🍃楼层 ——*/


.mes .mesIDDisplay {
    position: fixed;
    top: 163px;/*楼层上下*/
    left: -10px; /*楼层左右*/
  transform: none;            /* 移除所有变换效果 */
    z-index: 2;
    margin-top: 0px;
    text-align: left;           /* 文字左对齐 */
    width: auto;                /* 宽度自适应内容 */
    white-space: nowrap;        /* 防止文字换行 */
    padding: 0 10px;            /* 添加左右内边距 */
    display: inline-flex; 
    align-items: center;  
    gap: 2px;            /* 【左右文字间距】 */

    cursor: default;
    opacity: 1;
    font-size: calc(var(--mainFontSize) * 0.75);
    font-weight: 300;
    color: #a3a36b;      /* 【颜料🎨】【主文字颜色】 */
transform: rotate(0deg); /* 旋转 */
}


/* 左侧文字 */
.mes .mesIDDisplay::before {
    content: var(--left-text, ""); /* 【左侧文字内容】 */
    white-space: nowrap;  
    color: var(--left-color, #FFC67F); /* 【颜料🎨】【左侧文字颜色】 */
    font-weight: 300;
}

/* 右侧文字 */
.mes .mesIDDisplay::after {
    content: var(--right-text, ""); /* 【右侧文字内容】 */
    white-space: nowrap;  
    color: var(--right-color, #FFC67F); /* 【颜料🎨】【右侧文字颜色】 */
    font-weight: 300;
}

/*—— 🍃基础信息【时间戳、角色昵称等】 ——*/

/* ⭕️消息文字上边距留白核心调整 */
.mes_block {
  position: relative;
  margin-top: -120px;  
  overflow: visible;
}

/* ⭕️角色名称核心调整 */
.mes_block .ch_name {
  position: relative;
  top:209px; /* 上下 */
  left: 99px;
  max-width: calc(100% - 105px); 
  min-height: 0px;
  z-index: 10; 
  font-size: 0.70em;
  font-weight: 500;
  letter-spacing: 0.9px;
  white-space: nowrap;
  transform: rotate(0deg); /* 旋转 */
  color: #baba9d !important; 
  text-shadow: none !important;
  -webkit-text-stroke: 0 !important;
}
/* 左侧文字 */
.mes_block .ch_name::before {
  content: "";       /*左侧文字 */
  font-size: 1em;
  color: #9b7f80;            /* 左侧文字颜色 */
  display: inline;
  padding-right: -0px;        /* 右侧间距（分隔时间戳） */
  pointer-events: none;
}

/* ⭕️时间戳核心调整 */
.timestamp {
  position: absolute;
  top: 255px;                /* 上下 */
  left: 223px;                /* 左右 */
  width: 300%; 
  font-size: 0.95em;            /* 字体大小 */
  font-weight: 300;          /* 字体粗细 */
  transform: rotate(0deg);   /* 旋转 */
  white-space: nowrap;
  color: #7A7A7A !important; 
  opacity: 1 !important;
}

/* 左侧文字 */
.timestamp::before {
  content: "";       /*左侧文字 */
 font-size: 1em;
  color: #F3DAE5;            /* 左侧文字颜色 */
  display: inline;
  padding-right: 0px;        /* 右侧间距（分隔时间戳） */
  pointer-events: none;
}

/* 右侧文字 */
.timestamp::after {
  content: "";       /* 右侧文字 */
font-size: 1em;
  color: #F3DAE5;            /* 右侧文字颜色 */
  display: inline;
  padding-left: 0px;         /* 左侧间距（分隔时间戳） */
  pointer-events: none;
}


/* ⭕️编辑按钮核心调整 */
.mes_buttons {
  position: relative;
  top: -30px; /*编辑按钮上下*/
  left: 19px;/*编辑按钮左右*/
  z-index: 30;
  padding: 20px; 
  min-height: 30px;
  box-sizing: border-box;
  transform: rotate(0deg); /* 旋转 */
}

.mes_edit_buttons {
    display: none;
    flex-direction: row;
    column-gap: 5px;
    float: right;
    cursor: pointer;
    padding-bottom: 5px;
    filter: none; /*移除阴影*/
    transition: 0.3s ease-in-out;

    /* ⭕编辑菜单位置核心调整⭕ */
    position: relative;
    top: 65px;  /* 负数上移 | 正数下移  */
    right: 120px;   /* 负数右移 | 正数左移  */

  transform: rotate(-0deg); /* 旋转 */
}
.mes_edit_down.menu_button.fa-solid.fa-chevron-down.interactable.disabled {
    filter: none !important;
}
.mes_button, .extraMesButtons>div {
cursor: pointer;
    transition: opacity 0.2s ease-in-out;
    filter: none !important;
    /* ⭕设置省略号菜单颜色 */
    color: #a9b39b !important;
opacity: 0.7 !important; 
}

/*—— 计时器&字符——*/
.mes {
  position: relative; 
}

.mes .mes_timer,
.mes .tokenCounterDisplay {
  position: fixed; 
  z-index: 3; 
  cursor: default;
opacity: 1;/*透明度*/
  white-space: nowrap; 
  font-size: calc(var(--mainFontSize) * 0.75);/*文字大小*/
  font-weight: 300;/*文字粗细*/
  padding: 0;
  top: var(--element-top, 240px);
  left: var(--element-left, 50%);
  transform: translateX(var(--element-translate, -50%));
transform: rotate(0deg); /* 旋转 */
}


/* === ⭕️计时器核心 === */
.mes .mes_timer {
  text-align: left;
  --element-top: var(--counter-top, 163px); /* 【🍃字符计数器上下】 */
  --element-left: var(--counter-left, 152%); /* 【🍃字符计数器左右】 */
  --element-translate: var(--counter-translate, -0%);

  /* 文字内容控制 */
  --timer-prefix: ""; /* 【🍃前缀】 */
  --timer-suffix: ""; /* 【🍃后缀】 */

  --timer-main-color: #a3a36b; /* 【🍃计时器颜色】 */
  --timer-prefix-color: #000000; /* 【🍃前缀颜色】 */
  --timer-suffix-color: #bcbcbc; /* 【🍃后缀颜色】 */

  color: var(--timer-main-color);
}

/* 计时器文字控制 */
.mes .mes_timer::before {
content: var(--timer-prefix); /* 前缀文字 */
  color: var(--timer-prefix-color);
  padding-right: 9px;
}
.mes .mes_timer::after {
  content: var(--timer-suffix); /* 后缀文字 */
  color: var(--timer-suffix-color);
  padding-left: 0px;
}

/* === 字符计数器单独设置 === */
.mes .tokenCounterDisplay {
  text-align: left;
  --element-top: var(--counter-top, 163px); /* 【🍃字符计数器上下】 */
  --element-left: var(--counter-left, 80%); /* 【🍃字符计数器左右】 */
  --element-translate: var(--counter-translate, -0%); 

  --counter-prefix: ""; /* 【🍃前缀】 */
  --counter-suffix: ""; /* 【🍃后缀】 */

  --counter-main-color: #a3a36b; /* 【🍃计数器颜色】 */
    --counter-prefix-color: #C5D5DF; /* 【🍃前缀颜色】 */
  --counter-suffix-color: #C5D5DF; /* 【🍃后缀颜色】 */
  color: var(--counter-main-color);

}

.mes .tokenCounterDisplay::before {
  content: var(--counter-prefix); /* 前缀文字 */
  color: var(--counter-prefix-color);
  padding-right: 0px;
}
.mes .tokenCounterDisplay::after {
  content: var(--counter-suffix); /* 后缀文字 */
  color: var(--counter-suffix-color);
  padding-left: 0px;
}
/*—— ⭕️外显思维链 ——*/
.mes_reasoning_header::before {
  content: "";
  position: absolute;
  top: -2%;
  left: -25px;
  transform: translateY(-50%);
  width: 45px;
  height: 45px;
  background-image: url('https://iili.io/fbQ1atI.png'); 
  background-size: contain;
  background-repeat: no-repeat;
  filter: drop-shadow(0 0 3px rgba(255, 255, 255, 0));
  transition: all 0.3s ease;
  z-index: 1;
}
.mes_reasoning_header {
  position: absolute;
  z-index: 9999;
  top: 160px;/*思维链上下*/
  left: 55%;/*思维链左右*/
  transform: translateX(-50%);
  cursor: pointer;
  user-select: none;
  font-size: calc(var(--mainFontSize) * 0.75);
  transition: all 0.3s ease;
  padding: 0px 10px;
background: none !important;
  border: 0px solid #ffffff;
  border-radius: 0px;
 box-shadow:
none;
  color: #A4A4A4;
}

.mes_reasoning_header:hover {
  transform: translateX(-50%) translateY(2px);
  opacity: 0.5;
  background: #ffffff; 
}

.mes_reasoning_header_title {
  position: relative;
  display: inline-block;
  top: 0px;
  left: -0px;
  color: #BA97A6; 
  font-weight: 300;
}

.mes_reasoning {
  position: relative;
  top: -190px;
  display: block;
  margin: 390px 0px -400px 20px;

  color: #696947;
border: 0px solid #ffffff;
background: url('https://iili.io/fbQEnR4.png') repeat-y !important;
background-size: 100% auto !important;
  box-shadow:
  0px 0px 4px rgba(101, 103, 63, 0.20);
  padding: 15px;
  line-height: 1.6;
  border-radius: 0px;

  background-image: none;
  background-size: cover;
  background-position: center;
}

.mes_reasoning_header_title {
  /* 隐藏原始文本 */
  font-size: 0; 
  color: transparent; 
}
/* 隐藏箭头@hr */
.mes_reasoning_arrow {
    display: none !important;
}
.mes_reasoning_header_title::before {
  /*⭕️思维链文字diy */
  content: "";
