    left: 10px;/* 设置图标距离左边的位置 */
    top: 50%;/* 垂直居中对齐 */
    transform: translateY(-50%);
    width: 37px;/* 宽度 */
    height: 37px;/* 高度 */
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
opacity: 1 !important;
}

/* 成功 (Success) 通知的自定义图标 */
.toast-success::before {
    background-image: url("https://iili.io/fbQ1lnt.png");
}

/* 错误 (Error) 通知的自定义图标 */
.toast-error::before {
    background-image: url("https://iili.io/fbQ1TFa.png");
}

/* 信息 (Info) 通知的自定义图标 */
.toast-info::before {
    background-image: url("https://iili.io/fbQ1McG.png");
}

/* 警告 (Warning) 通知的自定义图标 */
.toast-warning::before {
    background-image: url("https://iili.io/fbQ1TFa.png");
}

/* 消息文字样式 */
.toast-title {
    color: #696947;
    font-size: 12px;
}

.toast-message {
    color: #696947 !important ;
    font-size: 12px !important ;
} 

